package br.com.swconsultoria.nfe;

import org.junit.Before;
import org.junit.Test;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class GenerateReportTests {

    private ConsultaTributacao.ValidationReport report;

    @Before
    public void setUp() {
        report = new ConsultaTributacao.ValidationReport();
    }

    @Test
    public void testGenerateReportWithPerfectStructure() {
        // Given: All lists are empty and strict conversion is successful
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("=== RELATORIO DE VALIDACAO ==="));
        assertTrue(result.contains("ESTRUTURA 100% COMPATIVEL"));
        assertTrue(result.contains("Nenhum campo extra no JSON"));
        assertTrue(result.contains("Nenhum campo faltando"));
        assertTrue(result.contains("Todos os tipos estao corretos"));
        assertTrue(result.contains("Conversao estrita: SUCESSO"));
    }

    @Test
    public void testGenerateReportWithExtraFields() {
        // Given
        Set<String> extraFields = new HashSet<>();
        extraFields.add("unknownField1");
        extraFields.add("unknownField2");
        report.extraFields = extraFields;
        report.missingFields = new HashSet<>();
        report.typeErrors = new HashMap<>();
        report.strictConversionSuccess = true;

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("ATENCAO: Campos EXTRAS no JSON (nao mapeados no DTO):"));
        assertTrue(result.contains("- unknownField1"));
        assertTrue(result.contains("- unknownField2"));
    }

    @Test
    public void testGenerateReportWithMissingFields() {
        // Given
        Set<String> missingFields = new HashSet<>();
        missingFields.add("requiredFieldA");
        report.missingFields = missingFields;
        report.extraFields = new HashSet<>();
        report.typeErrors = new HashMap<>();
        report.strictConversionSuccess = true;

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("ATENCAO: Campos FALTANDO no JSON (esperados no DTO):"));
        assertTrue(result.contains("- requiredFieldA"));
    }

    @Test
    public void testGenerateReportWithTypeErrors() {
        // Given
        Map<String, String> typeErrors = new HashMap<>();
        typeErrors.put("age", "Esperado Integer, encontrado String");
        typeErrors.put("active", "Esperado Boolean, encontrado String");
        report.typeErrors = typeErrors;
        report.extraFields = new HashSet<>();
        report.missingFields = new HashSet<>();
        report.strictConversionSuccess = true;

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("ERRO: Incompatibilidade de tipos:"));
        assertTrue(result.contains("- age: Esperado Integer, encontrado String"));
        assertTrue(result.contains("- active: Esperado Boolean, encontrado String"));
    }

    @Test
    public void testGenerateReportWithAllValidationErrors() {
        // Given
        Set<String> extraFields = new HashSet<>();
        extraFields.add("extra");
        report.extraFields = extraFields;

        Set<String> missingFields = new HashSet<>();
        missingFields.add("missing");
        report.missingFields = missingFields;

        Map<String, String> typeErrors = new HashMap<>();
        typeErrors.put("field", "Type mismatch");
        report.typeErrors = typeErrors;

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("Campos EXTRAS no JSON"));
        assertTrue(result.contains("Campos FALTANDO no JSON"));
        assertTrue(result.contains("Incompatibilidade de tipos"));
        // Ensure no "100% compativel" message is present
        assertTrue(!result.contains("ESTRUTURA 100% COMPATIVEL"));
    }

    @Test
    public void testGenerateReportWithStrictConversionFailed() {
        // Given
        report.strictConversionSuccess = false;
        report.strictConversionError = "Erro de formato invalido";
        report.extraFields = new HashSet<>();
        report.missingFields = new HashSet<>();
        report.typeErrors = new HashMap<>();

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("Conversao estrita: FALHOU"));
        assertTrue(result.contains("Erro: Erro de formato invalido"));
    }

    @Test
    public void testGenerateReportWithArrayDetected() {
        // Given
        report.arrayDetected = true;
        report.arraySize = 5;
        report.extraFields = new HashSet<>();
        report.missingFields = new HashSet<>();
        report.typeErrors = new HashMap<>();
        report.strictConversionSuccess = true;

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("Array detectado com 5 elemento(s)"));
        assertTrue(result.contains("Validacao realizada no primeiro elemento"));
    }

    @Test
    public void testGenerateReportWithArrayDetectedAndErrors() {
        // Given
        report.arrayDetected = true;
        report.arraySize = 1;
        report.strictConversionSuccess = false;
        report.strictConversionError = "Parse error";

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("Array detectado com 1 elemento(s)"));
        assertTrue(result.contains("Validacao realizada no primeiro elemento"));
        assertTrue(result.contains("Conversao estrita: FALHOU"));
        assertTrue(result.contains("Erro: Parse error"));
    }

    @Test
    public void testGenerateReportStrictConversionSuccessWithoutError() {
        // Given: Strict success is true, error is null
        report.strictConversionSuccess = true;
        report.strictConversionError = null;
        report.extraFields = new HashSet<>();
        report.missingFields = new HashSet<>();
        report.typeErrors = new HashMap<>();

        // When
        String result = report.generateReport();

        // Then
        assertTrue(result.contains("Conversao estrita: SUCESSO"));
